import{_ as n,o as i,c as t,ae as r}from"./chunks/framework.BvHJbMD4.js";const m=JSON.parse('{"title":"TEIL 1 – DIE SCHILLERNDE WITWE","description":"","frontmatter":{},"headers":[],"relativePath":"drehbuch/teil-1-die-schillernde-witwe.md","filePath":"drehbuch/teil-1-die-schillernde-witwe.md"}'),s={name:"drehbuch/teil-1-die-schillernde-witwe.md"};function a(d,e,h,o,l,c){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="teil-1-–-die-schillernde-witwe" tabindex="-1">TEIL 1 – DIE SCHILLERNDE WITWE <a class="header-anchor" href="#teil-1-–-die-schillernde-witwe" aria-label="Permalink to &quot;TEIL 1 – DIE SCHILLERNDE WITWE&quot;">​</a></h1><p><strong>EXT. WIENER BELVEDERE – TAG (ARCHIVMATERIAL/DROHNENAUFNAHMEN)</strong></p><p>Elegante Drohnenaufnahmen schweben über das barocke Belvedere, schwenken auf die modernen Anbauten der Heidi Horten Collection. Ein Schnitt auf historische Schwarz-Weiß-Aufnahmen von Wiener Kaufhäusern der 1930er Jahre.</p><p><strong>NARRATOR (V.O., leicht zynisch, nachdenklich)</strong> Wien. Eine Stadt, gebaut auf Geschichte. Und Geschichten. Manche schillernd, manche dunkel. Und manchmal, da verschwimmen die Farben, bis man nicht mehr weiß, was echt ist und was nur… gut aussehen soll.</p><p><strong>INT. HEIDI HORTEN COLLECTION – TAG (MODERN, LICHTDURCHFLUTET)</strong></p><p>Kamera gleitet über exquisite Kunstwerke: Picassos, Basquiats, Warhols. Perfekt ausgeleuchtet. Besucher, elegant gekleidet, flanieren bewundernd. Fokus auf einer älteren, makellosen Frau in Chanel – HEIDI HORTEN (80er), wie sie lächelnd ein Mikrofon entgegennimmt.</p><p><strong>HEIDI HORTEN</strong> (leise, charmant, Wiener Akzent) Kunst war immer meine Leidenschaft. Sie bereichert das Leben. Und sie… verbindet.</p><p><strong>NARRATOR (V.O.)</strong> Verbindet. Ein schönes Wort. Besonders, wenn man bedenkt, wie die Fundamente dieses Reichtums einst verbunden wurden. Mit dem, was man heute… nennen würde: Marktbereinigung.</p><p><strong>INT. STUDIO – INTERVIEW – TAG (MODERN, MINIMALISTISCH)</strong></p><p>DR. ANNA BREUER (50er, Historikerin, scharfzüngig), sitzt vor einem neutralen Hintergrund.</p><p><strong>DR. BREUER</strong> Helmut Horten, der Ehemann der Witwe, war ein Pionier. Nicht nur im Einzelhandel. Auch in der Kunst der Aneignung. Das System der Arisierung bot ihm… einzigartige Möglichkeiten.</p><p><strong>ARCHIVMATERIAL (SCHWARZ-WEISS)</strong></p><p>Schnelle Schnitte: Historische Zeitungsartikel über Arisierung. Bilder von jüdischen Geschäften, die &quot;übernommen&quot; werden. Ein junger HELMUT HORTEN (20er/30er), selbstbewusst, in einem Anzug, in den 1930er Jahren. Er lächelt.</p><p><strong>NARRATOR (V.O.)</strong> Ein junger Mann, der zur richtigen Zeit am richtigen Ort war. Oder am falschen Ort – je nachdem, auf welcher Seite des Ladentisches man stand. Er kaufte. Was andere verloren. Und legte damit den Grundstein für ein Imperium. Und für eine Sammlung, die heute… unbezahlbar ist.</p><p><strong>INT. HEIDI HORTEN COLLECTION – GANG – TAG</strong></p><p>Heidi Horten geht an einer Wand mit Fotografien vorbei, die ihren Mann zeigen. Sie bleibt vor einem Bild von HELMUT HORTEN (älter, imposant) stehen. Sie lächelt wehmütig.</p><p><strong>HEIDI HORTEN</strong> (V.O., leiser) Er war ein Visionär. Ein Mann, der wusste, was er wollte. Und wie man es bekommt.</p><p><strong>INT. STUDIO – INTERVIEW</strong></p><p>DR. BREUER schüttelt leicht den Kopf.</p><p><strong>DR. BREUER</strong> Man bekommt es, indem man die Augen schließt. Oder sie ganz weit aufmacht für die Gelegenheiten, die der historische Moment bietet. Horten hatte ein Gespür dafür. Ein… feines Gespür.</p><p><strong>NARRATOR (V.O.)</strong> Fein. So wie die Punkte eines Pointillisten. Einzeln kaum wahrnehmbar. Doch zusammen… formen sie ein ganzes Bild. Ein Bild von Geld. Und Macht. Und der sehr österreichischen Kunst, die Herkunft mancher Dinge… elegant zu übermalen.</p><p><strong>SCENE 3: INT. CAFÉ CENTRAL – TAG (ARCHIVMATERIAL/REKONSTRUKTION)</strong></p><p>Historische Aufnahmen vom Café Central. Später eine rekonstruierte Szene: Zwei HERREN (50er, Anwälte oder Geschäftsmänner) unterhalten sich gedämpft. Einer schiebt dem anderen diskret einen Umschlag zu.</p><p><strong>NARRATOR (V.O.)</strong> Der Pointillismus des Geldes. Eine Kunstform, die in den Salons und Hinterzimmern dieser Stadt perfektioniert wurde. Kleine Beträge. Unauffällige Zahlungen. Freundschaftsdienste. Alles getarnt als Teil des normalen Geschäfts. Aber wenn man genau hinsieht…</p><p><strong>INT. HEIDI HORTEN COLLECTION – NACHT</strong></p><p>Das Museum ist leer. Die Kunstwerke leuchten im Licht. Kamera fokussiert auf ein abstraktes Gemälde. Ein Spot erhellt es dramatisch.</p><p><strong>NARRATOR (V.O.)</strong> …dann sieht man die Punkte. Die Flecken. Die Schatten. Und man fragt sich: Wie viel Wahrheit verträgt so viel Schönheit? Und was kostet es wirklich, wenn die Vergangenheit… einfach so verblasst?</p><p><strong>FADE OUT.</strong></p>',28)])])}const g=n(s,[["render",a]]);export{m as __pageData,g as default};
